it('calls the API method', function (string $method, Closure $call, array $parameters, array $stub, ?Closure $check): void {
    Http::fake(['*' => Http::response(['status' => 'SUCCESS'] + $stub)]);

    $result = $call(baseLinkerClient());

    Http::assertSent(static function (Request $request) use ($method, $parameters): bool {
        $payload = json_decode((string) ($request->data()['parameters'] ?? ''), true);

        return $request->url() === 'https://api.baselinker.com/connector.php'
            && $request->hasHeader('X-BLToken', TEST_TOKEN)
            && ($request->data()['method'] ?? null) === $method
            && $payload == $parameters;
    });
    Http::assertSentCount(1);

    if ($check !== null) {
        $check($result);
    }
})->with('api methods');
